#include <gssapi/gssapi.h>

OM_uint32 process_spnego_continuation(OM_uint32 *minstat, gss_buffer_t buf, gss_ctx_id_t *ctx, gss_buffer_t *responseToken, gss_buffer_t *mechListMIC, OM_uint32 *negState, send_token_flag *return_token) {
    OM_uint32 minor_status = 0;
    OM_uint32 major_status;
    gss_OID mech;
    gss_buffer_desc token = GSS_C_EMPTY_BUFFER;

    *minstat = 0;

    if (!buf || !buf->length || !buf->value) {
        return GSS_S_BAD_SIG;
    }

    if (!ctx || !responseToken || !mechListMIC || !negState || !return_token) {
        return GSS_S_FAILURE;
    }

    if (buf->length < 2) {
        return GSS_S_BAD_SIG;
    }

    if (((unsigned char *)buf->value)[0] != 0x60) {
        return GSS_S_BAD_SIG;
    }

    if (((unsigned char *)buf->value)[1] != 0x06) {
        return GSS_S_BAD_SIG;
    }

    major_status = gss_unwrap(minor_status, *ctx, buf, &token, NULL, NULL, NULL);
    if (major_status != GSS_S_COMPLETE) {
        return GSS_S_FAILURE;
    }

    major_status = gss_import_name(minor_status, &token, GSS_C_NT_HOSTBASED_SERVICE, &mech);
    if (major_status != GSS_S_COMPLETE) {
        gss_release_buffer(minor_status, &token);
        return GSS_S_FAILURE;
    }

    *negState = GSS_C_CONTINUE_NEEDED;
    *return_token = TRUE;

    if (token.length > 0) {
        responseToken->length = token.length;
        responseToken->value = token.value;
    } else {
        responseToken->length = 0;
        responseToken->value = NULL;
    }

    if (mechListMIC->length > 0) {
        mechListMIC->length = mechListMIC->length;
        mechListMIC->value = mechListMIC->value;
    } else {
        mechListMIC->length = 0;
        mechListMIC->value = NULL;
    }

    gss_release_buffer(minor_status, &token);

    return GSS_S_CONTINUE_NEEDED;
}
